const today=dayKey();let date=today,view='today',history=[],running=null,elapsed=0;let livePosition=null,liveEtas={},locationWatch=null,nearbyEnabled=false,routeBusy=false,lastRouteAt=0,lastRoutePosition=null,routeGeneration=0,nearbyMessage='',replanQueued=false;let motionEnabled=true,lastAnimatedView=null,lastRingProgress=0;try{motionEnabled=localStorage.getItem('lbl-motion')!=='off'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches}catch{}document.documentElement.dataset.motion=motionEnabled?'on':'off';
const defaults={tasks:[],events:[],energy:'medium',start:'09:00',end:'21:00',buffer:10,dump:'',notify:false,startingAddress:'',startingCoords:null};let cloudReady=false,cloudRevision=0,cloudTimer,cloudBusy=false,cloudDirty=false,cloudBlocked=false,lastQueued='',cloudUser='';let state;try{state={...defaults,...JSON.parse(localStorage.getItem('lbl-v1')||'{}')}}catch{state={...defaults}};
let lastLocal=JSON.stringify(state);const save=()=>{try{const serialized=JSON.stringify(state);if(serialized!==lastLocal&&!cloudReady)localStorage.setItem('lbl-cloud-pending','1');lastLocal=serialized;localStorage.setItem('lbl-v1',serialized);$('#saved').textContent=cloudReady?'Saving…':'Loading saved planner…'}catch{$('#saved').textContent='Storage full — export a backup'}if(cloudReady)queueCloud()};const snapshot=()=>{history.push(JSON.stringify(state));if(history.length>30)history.shift()};
