function updateNearbyStatus(){if($('#nearby-status'))$('#nearby-status').textContent=nearbyMessage}
function distanceMeters(a,b){const r=Math.PI/180,x=(b.lon-a.lon)*r*Math.cos((a.lat+b.lat)*r/2),y=(b.lat-a.lat)*r;return Math.sqrt(x*x+y*y)*6371000}
