let nudged=new Set();setInterval(()=>{if(running){elapsed++;if($('#timer'))$('#timer').textContent='Focus time: '+Math.floor(elapsed/60)+'m '+elapsed%60+'s'}if(!state.notify)return;const now=new Date(),m=now.getHours()*60+now.getMinutes();for(const t of state.tasks.filter(t=>!t.done&&t.date===dayKey(now)&&t.at===m)){const key=t.id+t.date+t.at;if(nudged.has(key))continue;nudged.add(key);toast('Time for: '+t.title);if('Notification'in window&&Notification.permission==='granted')new Notification('Your next little thing',{body:t.title+' · '+t.duration+' minutes'})}},1000);
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function backup(){download(JSON.stringify(state,null,2),'little-by-little-backup.json','application/json')}
async function restore(file){if(!file)return;try{const s=JSON.parse(await file.text());if(!Array.isArray(s.tasks)||!Array.isArray(s.events)||!/^\d\d:\d\d$/.test(s.start)||!/^\d\d:\d\d$/.test(s.end)||!Number.isFinite(s.buffer)||s.tasks.some(t=>typeof t.title!=='string'||!Number.isFinite(t.duration)||!/^\d{4}-\d{2}-\d{2}$/.test(t.date))||s.events.some(e=>typeof e.title!=='string'||!Number.isFinite(e.start)||!Number.isFinite(e.end)))throw Error();open('<h2>Restore your backup?</h2><p class="help">This replaces the planner on this device. You can undo the restore.</p><div class="dialog-actions"><button onclick="closeModal()">Cancel</button><button class="primary" id="restore-confirm">Restore</button></div>');$('#restore-confirm').onclick=()=>{snapshot();state={...defaults,...s,notify:false};save();closeModal();render();toast('Your backup is restored.')}}catch{toast('That backup could not be read. Use a Little by Little JSON backup.')}}
function exportIcs(){const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Little by Little//Planner//EN'];let tasks=state.tasks.filter(t=>!t.done&&t.at!=null);if(!tasks.length)return toast('Schedule a few tasks before exporting.');for(const t of tasks){let stamp=m=>t.date.replaceAll('-','')+'T'+clock(m).replace(':','')+'00';rows.push('BEGIN:VEVENT','UID:'+t.id+'@littlebylittle','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,''),'DTSTART:'+stamp(t.at),'DTEND:'+stamp(t.at+t.duration),'SUMMARY:'+t.title.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),'END:VEVENT')}rows.push('END:VCALENDAR');download(rows.join('\r\n'),'little-by-little-tasks.ics','text/calendar')}
async function importIcs(file){if(!file)return;try{const text=(await file.text()).replace(/\r?\n[ \t]/g,''),parts=text.split('BEGIN:VEVENT').slice(1),events=[];let skipped=0;for(const p of parts){const get=k=>p.match(new RegExp('(?:^|\\n)'+k+'(?:;[^:]*)?:([^\\r\\n]+)'))?.[1];let start=get('DTSTART'),end=get('DTEND');if(get('RRULE')||/DTSTART;TZID=/.test(p)||!start||!end){skipped++;continue}function parse(v){if(/^\d{8}$/.test(v))return{date:v.slice(0,4)+'-'+v.slice(4,6)+'-'+v.slice(6,8),m:0};if(!/^\d{8}T\d{6}Z?$/.test(v))return null;let iso=v.slice(0,4)+'-'+v.slice(4,6)+'-'+v.slice(6,8)+'T'+v.slice(9,11)+':'+v.slice(11,13)+':'+v.slice(13,15)+(v.endsWith('Z')?'Z':'');const d=new Date(iso);return{date:dayKey(d),m:d.getHours()*60+d.getMinutes()}}const a=parse(start),b=parse(end);if(!a||!b){skipped++;continue}if(start.length===8){events.push({id:get('UID')||crypto.randomUUID(),title:(get('SUMMARY')||'All-day commitment'),date:a.date,start:0,end:1440});continue}if(a.date!==b.date||b.m<=a.m){skipped++;continue}events.push({id:get('UID')||crypto.randomUUID(),title:(get('SUMMARY')||'Calendar event').replace(/\\n/g,' ').replace(/\\([,;\\])/g,'$1'),date:a.date,start:a.m,end:b.m})}snapshot();for(const e of events){const i=state.events.findIndex(x=>x.id===e.id);if(i>=0)state.events[i]=e;else state.events.push(e)}save();render();toast(`${events.length} commitments imported. ${skipped} unsupported or recurring events skipped. Times use this device’s timezone; verify imported times.`)}catch{toast('Could not read this calendar file.')}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo({top:0,behavior:'instant'})});render();bootCloud();

function cloudStatus(text){$('#saved').textContent=text}
function queueCloud(){const payload=JSON.stringify(state);if(payload===lastQueued){if(!cloudDirty&&!cloudBusy)cloudStatus('Saved to your account ✓');return}lastQueued=payload;cloudDirty=true;try{localStorage.setItem('lbl-cloud-pending','1')}catch{}cloudStatus('Saving…');clearTimeout(cloudTimer);cloudTimer=setTimeout(pushCloud,650)}
async function pushCloud(){if(!cloudReady||cloudBusy||!cloudDirty||cloudBlocked)return;cloudBusy=true;cloudDirty=false;const payload=lastQueued;try{const r=await fetch('/api/planner',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:JSON.parse(payload),revision:cloudRevision})});const data=await r.json();if(r.status===409){cloudBlocked=true;cloudDirty=true;cloudStatus('Changed elsewhere · click to resolve');toast('Another tab or device updated your planner. Click the save status to resolve.');return}if(!r.ok)throw Error(data.error||'Save failed');cloudRevision=data.revision;try{localStorage.setItem('lbl-cloud-revision',String(cloudRevision));if(!cloudDirty)localStorage.removeItem('lbl-cloud-pending')}catch{}cloudStatus(cloudDirty?'Saving…':'Saved to your account ✓')}catch(e){cloudDirty=true;cloudStatus('Not synced · click to retry');toast('Couldn’t sync yet. Your device copy is safe.')}finally{cloudBusy=false;if(cloudDirty&&!cloudBlocked&&$('#saved').textContent==='Saving…')setTimeout(pushCloud,100)}}
async function bootCloud(){cloudStatus('Loading your saved planner…');document.body.classList.add('sync-loading');try{const r=await fetch('/api/planner',{cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error);cloudRevision=data.revision;cloudUser=data.userKey;const marker='lbl-migrated-'+cloudUser;const localPending=localStorage.getItem('lbl-cloud-pending')==='1',localRevision=Number(localStorage.getItem('lbl-cloud-revision')||0);let needsSave=false;
 if(data.state){if(localPending&&localRevision===cloudRevision){needsSave=true}else{const old=state;state={...defaults,...data.state};if(!localStorage.getItem(marker)){for(const kind of ['tasks','events'])for(const item of old[kind])if(!state[kind].some(t=>t.id===item.id)){state[kind].push(item);needsSave=true}if(old.dump&&old.dump!==state.dump){state.dump=[state.dump,old.dump].filter(Boolean).join('\n');needsSave=true}}else if(localPending){localStorage.setItem('lbl-recovery-copy',JSON.stringify(old));toast('Loaded your latest account planner. An unsynced device copy is available in My rhythm.')}}}else needsSave=true;
 localStorage.setItem(marker,'1');localStorage.setItem('lbl-cloud-revision',String(cloudRevision));cloudReady=true;lastQueued=needsSave?'':JSON.stringify(state);if(!needsSave)localStorage.removeItem('lbl-cloud-pending');render();if(needsSave)queueCloud();else cloudStatus('Saved to your account ✓');
 }catch(e){cloudStatus('Offline copy · click to retry');toast('Couldn’t load your account planner. Your device copy is available. Changes will stay here until you reconnect.')}finally{document.body.classList.remove('sync-loading');if(cloudReady&&localStorage.getItem('lbl-nearby-enabled')==='1'){nearbyEnabled=true;startNearbyWatch();render()}}}
$('#saved').style.cursor='pointer';$('#saved').setAttribute('role','button');$('#saved').tabIndex=0;$('#saved').onclick=()=>{if(cloudBlocked){open('<h2>Your planner changed elsewhere</h2><p class="help">To protect your saved tasks, this tab has stopped syncing. Download your current device copy, then load the latest account planner. Your current copy will also be kept in recovery.</p><div class="dialog-actions"><button onclick="backup()">Download this copy</button><button class="primary" onclick="resolveCloud()">Load latest saved planner</button></div>')}else if(!cloudReady)bootCloud();else if(cloudDirty)pushCloud();else toast('Your planner is saved to your account.')};$('#saved').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#saved').click()}};
function resolveCloud(){try{localStorage.setItem('lbl-recovery-copy',JSON.stringify(state));localStorage.removeItem('lbl-cloud-pending')}catch{}cloudBlocked=false;cloudDirty=false;cloudReady=false;closeModal();bootCloud()}
window.addEventListener('online',()=>{if(cloudReady)pushCloud();else bootCloud()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')pushCloud()});window.addEventListener('beforeunload',e=>{if(cloudDirty||cloudBusy){e.preventDefault();e.returnValue=''}});
function recovery(){const copy=localStorage.getItem('lbl-recovery-copy');if(copy)download(copy,'little-by-little-recovery.json','application/json');else toast('No recovery copy is needed right now.')}
let addressSequence=0,addressTimeout,addressAbort;
function setupAddressSearch(inputId='address',resultId='address-results',statusId='address-status'){const input=$('#'+inputId),results=$('#'+resultId),status=$('#'+statusId);if(!input)return;input.oninput=()=>{input.dataset.coords='';input.dataset.name='';input.dispatchEvent(new Event('place-editing'));clearTimeout(addressTimeout);addressAbort?.abort();const seq=++addressSequence,q=input.value.trim();results.replaceChildren();if(q.length<3){status.textContent='Type 3+ characters for suggestions, or use your own location label.';return}status.textContent='Looking for addresses…';addressTimeout=setTimeout(async()=>{addressAbort=new AbortController();try{const r=await fetch('/api/addresses?q='+encodeURIComponent(q)+(livePosition?'&lat='+livePosition.lat+'&lon='+livePosition.lon:''),{signal:addressAbort.signal});const data=await r.json();if(seq!==addressSequence||!input.isConnected)return;if(!r.ok)throw Error(data.error);status.textContent=data.results.length?'Choose a suggestion · © OpenStreetMap contributors / Photon':'No matches. Add a town or ZIP code, or keep your typed address.';results.replaceChildren();for(const item of data.results){const button=document.createElement('button');button.type='button';button.className='address-option';button.textContent=item.label;button.onclick=()=>{input.value=item.label;input.dataset.name=item.name||item.label;writeCoords(input,{lat:item.lat,lon:item.lon});results.replaceChildren();status.textContent='Address selected. Save the task to keep it.';input.dispatchEvent(new Event('place-selected'))};results.appendChild(button)}}catch(e){if(e.name!=='AbortError'&&seq===addressSequence)status.textContent='Address search is unavailable. You can still save your typed address.'}},700)}}

function readCoords(input){try{const p=JSON.parse(input.dataset.coords||'null');return p&&Number.isFinite(p.lat)&&Number.isFinite(p.lon)?p:null}catch{return null}}
function writeCoords(input,p){if(input)input.dataset.coords=p?JSON.stringify(p):''}

function getCurrentPosition(){return new Promise((resolve,reject)=>{if(!navigator.geolocation){reject(new Error('Location is unavailable in this browser. Choose a custom starting address instead.'));return}navigator.geolocation.getCurrentPosition(position=>resolve({lat:position.coords.latitude,lon:position.coords.longitude,accuracy:position.coords.accuracy,capturedAt:new Date(position.timestamp).toISOString()}),error=>reject(new Error(error.code===1?'Location access was blocked. Allow it in browser settings, or choose a custom starting address.':error.code===3?'Finding your location timed out. Try again, or choose a custom starting address.':'Couldn’t find your location. Try again, or choose a custom starting address.')),{enableHighAccuracy:true,timeout:15000,maximumAge:60000})})}
function setupSimplePlace(t){
 const input=$('#address'),status=$('#place-eta'),refresh=$('#update-location'),form=$('#taskform');let version=0,controller;
 function invalidate(){version++;controller?.abort();status.dataset.minutes='';status.textContent='Choose the matching store or address to calculate your drive.'}
 async function estimate(force=false){const coords=readCoords(input);if(!coords){status.textContent='Choose the right place from the search suggestions first.';return}const v=++version;controller?.abort();controller=new AbortController();refresh.disabled=true;status.dataset.minutes='';status.textContent='Finding your location and drive time…';try{
 if(force||!livePosition||Date.now()-livePosition.captured>120000){const p=await getCurrentPosition();if(v!==version||!form.isConnected)return;if(p.accuracy>1000)throw Error('Your location is too approximate. Try on your phone.');livePosition={lat:p.lat,lon:p.lon,captured:Date.now(),accuracy:p.accuracy}}
 const r=await fetch('/api/journey',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({points:[{lat:livePosition.lat,lon:livePosition.lon},coords]}),signal:controller.signal});const data=await r.json();if(v!==version||!form.isConnected)return;if(!r.ok)throw Error(data.error);const minutes=data.minutes[0]?.[1];if(minutes==null)throw Error('No driving route found for this location.');status.dataset.minutes=String(minutes);status.textContent='↗ About '+minutes+' min drive from where you are now. Your day will connect this stop to the others. No live traffic.';
 }catch(e){if(force)livePosition=null;if(v===version&&e.name!=='AbortError')status.textContent=e.message||'Couldn’t estimate the drive. Your task can still be saved.'}finally{if(v===version)refresh.disabled=false}}
 input.addEventListener('place-editing',()=>{invalidate();refresh.disabled=false});input.addEventListener('place-selected',()=>estimate());refresh.onclick=()=>estimate(true);
 if($('#pick-home'))$('#pick-home').onclick=()=>{invalidate();input.value=state.startingAddress||'Home';input.dataset.name='Home';writeCoords(input,state.startingCoords);estimate()};
 if(t.locationCoords)estimate();else if(!livePosition){status.textContent='Allow location access for nearby store suggestions and automatic drive times.';getCurrentPosition().then(p=>{if(!form.isConnected||p.accuracy>1000)return;livePosition={lat:p.lat,lon:p.lon,captured:Date.now(),accuracy:p.accuracy};if(readCoords(input))return;status.textContent='Location ready. Choose a store to see the drive.';if(input.value.trim().length>=3)input.dispatchEvent(new Event('input'))}).catch(()=>{if(form.isConnected)status.textContent='Choose a store, then allow location access to calculate the drive.'})}
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')stopNearbyWatch();else if(nearbyEnabled)startNearbyWatch()});

function syncMotionButtons(){document.querySelectorAll('.motion-toggle').forEach(b=>{b.textContent=motionEnabled?'◌ Pause animations':'◌ Turn animations on';b.setAttribute('aria-pressed',String(motionEnabled))})}
function toggleMotion(){if(!motionEnabled&&window.matchMedia('(prefers-reduced-motion: reduce)').matches){toast('Your device’s Reduce Motion setting is on. Animations will stay paused.');return}motionEnabled=!motionEnabled;try{localStorage.setItem('lbl-motion',motionEnabled?'on':'off')}catch{}document.documentElement.dataset.motion=motionEnabled?'on':'off';syncMotionButtons();if(!motionEnabled)document.querySelectorAll('.celebration').forEach(e=>e.remove())}
function animateScene(){syncMotionButtons();if(!motionEnabled)return;const root=$('#view');if(lastAnimatedView!==view){root.classList.remove('enter-scene');requestAnimationFrame(()=>root.classList.add('enter-scene'));lastAnimatedView=view;clearTimeout(window.sceneTimer);window.sceneTimer=setTimeout(()=>root.classList.remove('enter-scene'),1100)}const ring=$('.growth-ring');if(ring){const target=parseFloat(ring.style.getPropertyValue('--progress'))||0;ring.style.setProperty('--progress',lastRingProgress+'%');requestAnimationFrame(()=>requestAnimationFrame(()=>{if(ring.isConnected)ring.style.setProperty('--progress',target+'%')}));lastRingProgress=target}}
function celebrate(point){if(!motionEnabled||document.visibilityState==='hidden')return;const layer=document.createElement('div');layer.className='celebration';layer.setAttribute('aria-hidden','true');const x=point?.x??window.innerWidth/2,y=Math.max(30,Math.min(window.innerHeight-100,point?.y??window.innerHeight*.4));for(let i=0;i<18;i++){const petal=document.createElement('span');petal.className='celebration-petal';const angle=(i/18)*Math.PI*2,distance=55+Math.random()*55;petal.style.cssText='left:'+x+'px;top:'+y+'px;--dx:'+Math.cos(angle)*distance+'px;--dy:'+(Math.sin(angle)*distance+25)+'px;--rot:'+(Math.random()*380-190)+'deg;--delay:'+Math.random()*65+'ms;background:'+['#b99bd7','#e7b28d','#aec49b','#edd29d','#d6b6df'][i%5];layer.appendChild(petal)}document.body.appendChild(layer);document.documentElement.classList.add('is-celebrating');clearTimeout(window.flourishTimer);window.flourishTimer=setTimeout(()=>document.documentElement.classList.remove('is-celebrating'),1100);setTimeout(()=>layer.remove(),1400)}
syncMotionButtons();
